  const rot = (v) => { const x1r = v[0] * ca - v[1] * sa, y1r = v[0] * sa + v[1] * ca, z1 = v[2]; return [x1r, y1r * ce - z1 * se, y1r * se + z1 * ce]; };
  const L = [-0.32, -0.5, 0.8], LL = Math.hypot(L[0], L[1], L[2]); L[0] /= LL; L[1] /= LL; L[2] /= LL;
