      // surface's rim (sphere equator). Perimeter order is preserved so the polygon stays valid.
      const corners = [P[i][j], P[i + 1][j], P[i + 1][j + 1], P[i][j + 1]].filter((p) => isFinite(p.z));
      if (corners.length < 3) continue;
