// context), stroke:var(--plot-c1) would fall back to "none" → an INVISIBLE curve ("no graph").
const PLOT_PAL = ["var(--plot-c1,#237a68)", "var(--plot-c2,#3b82f6)", "var(--plot-c3,#ef4444)", "var(--plot-c4,#d97706)", "var(--plot-c5,#7c3aed)"];

