  const lbl = (ln) => { const q = /["'“”„]([^"'“”„]+)["'“”„]/.exec(ln); if (q) return q[1]; const w = /(?:label|name)\s*[:=]\s*([^\s,]+)/i.exec(ln); return w ? w[1] : null; };
