  if (/\\$/.test(last)) return false;                       // shell / make line continuation
  if (/[,+\-*/%=<>!&|^~?:.]$/.test(last)) return false;     // dangling operator
  if (/[([{]$/.test(last)) return false;                    // opened something and stopped
