  t = t.replace(/```firas-code[ \t]+\{[\s\S]*?\}[ \t]*\r?\n?/g, "");
  t = t.replace(/\{"filename":\s*"[^"]*"\s*,\s*"lang":\s*"[^"]*"\s*,\s*"ext":\s*"[^"]*"\s*,\s*"label":\s*"[^"]*"\}/g, "");
