    // Nothing finished and nothing planned = nothing worth resuming.
    if (!built.length && !(plan.steps && plan.steps.length)) return;
    cwResume.set(key, { plan, built: built.slice(), request, isEdit: !!isEdit, name, at: Date.now() });
