  const extOf = (p) => (/\.html?$/.test(p) ? "html" : /\.css$/.test(p) ? "css" : /\.m?jsx?$/.test(p) ? "js" : /\.py$/.test(p) ? "py" : /\.json$/.test(p) ? "json" : /\.md$/.test(p) ? "md" : "txt");
