    const add = (p) => { if (p && !seen.has(p) && focus.length < 6) { seen.add(p); focus.push(p); } };
    const isSub = (n, h) => { let i = 0; for (let j = 0; j < h.length && i < n.length; j++) if (h[j] === n[i]) i++; return i === n.length; };
